def _count_reasoning(i, role, last_user, reasoning_mode):
    """Whether the reasoning_content of message i is counted: 'all' counts
    every assistant; 'after_user' counts only assistant messages after the
    last user message."""
    if role != "assistant":
        return False
    if reasoning_mode == "all":
        return True
    # 'after_user'
    return last_user is None or i > last_user

