def _count_reasoning(i, role, last_user):
    """Whether the reasoning_content of message i is counted: 'all' = every
    assistant, 'after_user' = only assistant messages after the last user."""
    if role == "assistant":
        if last_user is None or i > last_user:
            return True
        return False
    return False
